TESTS['linear'] = '\n#include <cassert>\n#include <vector>\n#include <deque>\n#include <algorithm>\n#include <random>\n#include <set>\n\nstatic std::mt19937 rng(20261026);\nstatic int randInt(int lo, int hi) {\n    return lo + static_cast<int>(rng() % (hi - lo + 1));\n}\nstatic std::vector<int> seq(LinkList L) {\n    std::vector<int> v;\n    std::set<LNode *> seen;\n    for (LNode *p = L->next; p != NULL; p = p->next) {\n        assert(seen.insert(p).second); // Detect accidental cycle.\n        v.push_back(p->data);\n    }\n    return v;\n}\nstatic std::set<LNode *> nodes(LinkList L) {\n    std::set<LNode *> r;\n    for (LNode *p=L->next; p; p=p->next) {\n        assert(r.insert(p).second);\n    }\n    return r;\n}\nstatic LinkList make(const std::vector<int> &v) {\n    LinkList L = NULL;\n    CreateByTail(L, v.data(), static_cast<int>(v.size()));\n    return L;\n}\nstatic std::vector<int> randomVec(int n) {\n    std::vector<int> v(n);\n    for (int &x : v) x=randInt(-20,20);\n    return v;\n}\nstatic void sqTests() {\n    SqList L;\n    InitSqList(L);\n    std::vector<int> v;\n    for (int t=0; t<30000; ++t) {\n        int i=randInt(-1,static_cast<int>(v.size())+3);\n        int x=randInt(-100,100);\n        if (randInt(0,1)==0) {\n            bool ok=i>=1 && i<=static_cast<int>(v.size())+1 &&\n                    v.size()<static_cast<size_t>(MaxSize);\n            assert(SqInsert(L,i,x)==ok);\n            if (ok) v.insert(v.begin()+i-1,x);\n        } else {\n            bool ok=i>=1 && i<=static_cast<int>(v.size());\n            int removed=INT_MIN;\n            assert(SqDelete(L,i,removed)==ok);\n            if (ok) {\n                assert(removed==v[i-1]);\n                v.erase(v.begin()+i-1);\n            } else assert(removed==INT_MIN);\n        }\n        assert(L.length==static_cast<int>(v.size()));\n        assert(std::equal(v.begin(),v.end(),L.data));\n    }\n    InitSqList(L);\n    for(int i=0;i<MaxSize;++i) assert(SqInsert(L,i+1,i));\n    assert(!SqInsert(L,1,7));\n    for(int i=MaxSize-1;i>=0;--i) {\n        int x=-1;\n        assert(SqDelete(L,L.length,x) && x==i);\n    }\n}\nstatic void listTests() {\n    for(int t=0;t<2000;++t) {\n        auto v=randomVec(randInt(0,80));\n        LinkList L=make(v);\n        assert(seq(L)==v);\n        auto identity=nodes(L);\n        ReverseList(L);\n        auto rev=v; std::reverse(rev.begin(),rev.end());\n        assert(seq(L)==rev && nodes(L)==identity);\n        ReverseList(L);\n        assert(seq(L)==v);\n        int x=randInt(-25,25);\n        DeleteGreater(L,x);\n        auto keep=v;\n        keep.erase(std::remove_if(keep.begin(),keep.end(),\n                   [x](int z){return z>x;}),keep.end());\n        assert(seq(L)==keep);\n        DestroyList(L); assert(L==NULL);\n        CreateByHead(L,v.data(),static_cast<int>(v.size()));\n        assert(seq(L)==rev);\n        DestroyList(L);\n\n        L=make(v);\n        LNode *tail=L;\n        while(tail->next) tail=tail->next;\n        tail->next=L;\n        ReverseCircularList(L);\n        std::vector<int> circular;\n        LNode *p=L->next;\n        for(size_t i=0;i<v.size();++i) {\n            assert(p!=L);\n            circular.push_back(p->data);\n            p=p->next;\n        }\n        assert(p==L && circular==rev);\n        tail=L;\n        while(tail->next!=L) tail=tail->next;\n        tail->next=NULL;\n        DestroyList(L);\n    }\n    ReverseList(NULL); ReverseCircularList(NULL); DeleteGreater(NULL,0);\n    LinkList absent=NULL; DestroyList(absent);\n}\nstatic void mergeTests() {\n    for(int t=0;t<2000;++t) {\n        auto a=randomVec(randInt(0,35)),b=randomVec(randInt(0,35));\n        std::sort(a.begin(),a.end()); std::sort(b.begin(),b.end());\n        auto expect=a; expect.insert(expect.end(),b.begin(),b.end());\n        std::sort(expect.begin(),expect.end());\n        for(int direction=0;direction<2;++direction) {\n            LinkList A=make(a), B=make(b);\n            auto ids=nodes(A), bi=nodes(B); ids.insert(bi.begin(),bi.end());\n            bool ok=direction==0?MergeAscending(A,B):MergeDescending(A,B);\n            auto check=expect;\n            if(direction) std::reverse(check.begin(),check.end());\n            assert(ok && B==NULL && seq(A)==check && nodes(A)==ids);\n            DestroyList(A);\n        }\n    }\n    LinkList A=make({1,2}), B=NULL;\n    assert(!MergeAscending(A,B)); assert(!MergeDescending(A,B));\n    assert(!MergeAscending(A,A)); assert(!MergeDescending(A,A));\n    DestroyList(A);\n}\nstatic void pointerTests() {\n    assert(KthFromEnd(NULL,1)==NULL && FrontMiddle(NULL)==NULL);\n    for(int n=0;n<=100;++n) {\n        std::vector<int> v(n);\n        for(int i=0;i<n;++i) v[i]=i;\n        LinkList L=make(v);\n        for(int k=-1;k<=n+1;++k) {\n            auto p=KthFromEnd(L,k);\n            if(k<=0 || k>n) assert(p==NULL);\n            else assert(p && p->data==n-k);\n        }\n        auto p=FrontMiddle(L);\n        if(n==0) assert(p==NULL);\n        else assert(p && p->data==(n-1)/2);\n        DestroyList(L);\n    }\n}\nstatic int josephusOracle(int n,int s,int m) {\n    std::vector<int> v(n);\n    for(int i=0;i<n;++i) v[i]=i+1;\n    int cur=s-1;\n    while(v.size()>1) {\n        cur=(cur+m-1)%static_cast<int>(v.size());\n        v.erase(v.begin()+cur);\n    }\n    return v[0];\n}\nstatic void josephusTests() {\n    assert(Josephus(0,1,1)==0 && Josephus(1,0,1)==0);\n    assert(Josephus(1,2,1)==0 && Josephus(1,1,0)==0);\n    assert(Josephus(1,1,17)==1 && Josephus(5,1,3)==4);\n    for(int n=1;n<=45;++n)\n        for(int s=1;s<=n;++s)\n            for(int m=1;m<=13;++m)\n                assert(Josephus(n,s,m)==josephusOracle(n,s,m));\n}\nstatic void doubleTests() {\n    assert(!SwapWithPrev(NULL));\n    for(int n=1;n<=20;++n) {\n        for(int pos=0;pos<n;++pos) {\n            DNode *head=(DNode*)malloc(sizeof(DNode));\n            head->prior=NULL; head->next=NULL;\n            DNode *tail=head, *p=NULL;\n            for(int i=0;i<n;++i) {\n                DNode *q=(DNode*)malloc(sizeof(DNode));\n                q->data=i; q->prior=tail; q->next=NULL;\n                tail->next=q; tail=q;\n                if(i==pos) p=q;\n            }\n            assert(!SwapWithPrev(head));\n            assert(SwapWithPrev(p)==(pos>0));\n            std::vector<int> want(n);\n            for(int i=0;i<n;++i) want[i]=i;\n            if(pos>0) std::swap(want[pos],want[pos-1]);\n            DNode *q=head->next, *pre=head;\n            for(int x:want) {\n                assert(q && q->data==x && q->prior==pre);\n                pre=q; q=q->next;\n            }\n            assert(q==NULL);\n            while(head) {\n                DNode *next=head->next; free(head); head=next;\n            }\n        }\n    }\n}\nstatic void stackQueueTests() {\n    SqStack S; InitStack(S);\n    std::vector<int> v;\n    SqQueue Q; InitQueue(Q);\n    std::deque<int> d;\n    int x=777;\n    assert(!Pop(S,x) && !GetTop(S,x) && x==777);\n    assert(!DeQueue(Q,x) && !GetFront(Q,x) && x==777);\n    for(int i=0;i<MaxSize;++i) assert(Push(S,i));\n    assert(!Push(S,99));\n    for(int i=MaxSize-1;i>=0;--i) assert(Pop(S,x) && x==i);\n    for(int cycle=0;cycle<4;++cycle) {\n        for(int i=0;i<MaxSize-1;++i) assert(EnQueue(Q,i));\n        assert(!EnQueue(Q,99));\n        for(int i=0;i<MaxSize-1;++i) assert(DeQueue(Q,x) && x==i);\n    }\n    for(int t=0;t<50000;++t) {\n        int value=randInt(-1000,1000), op=randInt(0,2);\n        if(op==0) {\n            bool ok=v.size()<static_cast<size_t>(MaxSize);\n            assert(Push(S,value)==ok); if(ok) v.push_back(value);\n            ok=d.size()<static_cast<size_t>(MaxSize-1);\n            assert(EnQueue(Q,value)==ok); if(ok) d.push_back(value);\n        } else if(op==1) {\n            assert(Pop(S,x)==!v.empty());\n            if(!v.empty()){assert(x==v.back());v.pop_back();}\n            assert(DeQueue(Q,x)==!d.empty());\n            if(!d.empty()){assert(x==d.front());d.pop_front();}\n        } else {\n            assert(GetTop(S,x)==!v.empty());\n            if(!v.empty()) assert(x==v.back());\n            assert(GetFront(Q,x)==!d.empty());\n            if(!d.empty()) assert(x==d.front());\n        }\n        assert(StackEmpty(S)==v.empty());\n        assert(QueueEmpty(Q)==d.empty());\n        assert(QueueLength(Q)==static_cast<int>(d.size()));\n    }\n    SharedStack SS; InitSharedStack(SS);\n    std::vector<int> a,b;\n    assert(!SharedPush(SS,0,7) && !SharedPop(SS,3,x));\n    for(int i=0;i<MaxSize;++i) assert(SharedPush(SS,(i%2)+1,i));\n    assert(!SharedPush(SS,1,0) && !SharedPush(SS,2,0));\n    for(int i=MaxSize-1;i>=0;--i)\n        assert(SharedPop(SS,(i%2)+1,x) && x==i);\n    for(int t=0;t<40000;++t) {\n        int which=randInt(1,2),value=randInt(-500,500);\n        auto &ref=which==1?a:b;\n        if(randInt(0,1)==0) {\n            bool ok=a.size()+b.size()<static_cast<size_t>(MaxSize);\n            assert(SharedPush(SS,which,value)==ok);\n            if(ok) ref.push_back(value);\n        } else {\n            assert(SharedPop(SS,which,x)==!ref.empty());\n            if(!ref.empty()){assert(x==ref.back());ref.pop_back();}\n        }\n        assert(SS.top1+1==static_cast<int>(a.size()));\n        assert(MaxSize-SS.top2==static_cast<int>(b.size()));\n    }\n}\nint main() {\n    sqTests(); listTests(); mergeTests(); pointerTests();\n    josephusTests(); doubleTests(); stackQueueTests();\n    std::puts("PASS 01-08: sequence, ownership, pointers, ring, stack, queue");\n}\n'

TESTS['trees_graphs'] = '\n#include <algorithm>\n#include <cassert>\n#include <iostream>\n#include <numeric>\n#include <random>\n#include <vector>\nusing std::vector;\n\nBiTree TGNew(int x) {\n    BiTree p=(BiTree)malloc(sizeof(BiTNode));\n    p->data=x; p->lchild=p->rchild=NULL; return p;\n}\nvoid TGFree(BiTree p) {\n    if (!p) return;\n    TGFree(p->lchild); TGFree(p->rchild); free(p);\n}\nvoid TGSequences(BiTree p, vector<int>&pre, vector<int>&in) {\n    if (!p) return;\n    pre.push_back(p->data);\n    TGSequences(p->lchild,pre,in); in.push_back(p->data);\n    TGSequences(p->rchild,pre,in);\n}\nvoid TGTreeCheck(BiTree root) {\n    vector<BiTree> nodes;\n    vector<int> level, height;\n    if(root){nodes.push_back(root); level.push_back(1);}\n    int expectedHeight=0,leaves=0,width=0;\n    int counts[MaxSize+1]={0};\n    for(size_t i=0;i<nodes.size();++i){\n        BiTree p=nodes[i];\n        int d=level[i];\n        expectedHeight=std::max(expectedHeight,d);\n        width=std::max(width,++counts[d]);\n        if(!p->lchild&&!p->rchild) ++leaves;\n        if(p->lchild){nodes.push_back(p->lchild);level.push_back(d+1);}\n        if(p->rchild){nodes.push_back(p->rchild);level.push_back(d+1);}\n    }\n    bool balanced=true;\n    height.assign(nodes.size(),0);\n    for(int i=(int)nodes.size()-1;i>=0;--i){\n        int lh=0,rh=0;\n        for(int j=i+1;j<(int)nodes.size();++j){\n            if(nodes[j]==nodes[i]->lchild) lh=height[j];\n            if(nodes[j]==nodes[i]->rchild) rh=height[j];\n        }\n        height[i]=std::max(lh,rh)+1;\n        if(std::abs(lh-rh)>1) balanced=false;\n    }\n    assert(TreeHeight(root)==expectedHeight);\n    assert(TreeNodeCount(root)==(int)nodes.size());\n    assert(TreeLeafCount(root)==leaves);\n    assert(TreeWidth(root)==width);\n    assert(BalancedHeight(root)==(balanced?expectedHeight:-1));\n    vector<int> pre,in;\n    TGSequences(root,pre,in);\n    int out[MaxSize], path[MaxSize];\n    assert(InOrderIter(root,out)==(int)nodes.size());\n    assert(std::equal(in.begin(),in.end(),out));\n    bool sorted=true;\n    for(size_t i=1;i<in.size();++i) if(in[i-1]>=in[i]) sorted=false;\n    assert(JudgeBST(root)==sorted);\n    BiTree copy=BuildPreIn(pre.data(),0,in.data(),0,(int)nodes.size());\n    vector<int> pre2,in2; TGSequences(copy,pre2,in2);\n    assert(pre==pre2&&in==in2);\n    TGFree(copy);\n    int len=LongestRootLeafPath(root,path);\n    assert(len==expectedHeight);\n    BiTree p=root;\n    for(int i=0;i<len;++i){\n        assert(p&&p->data==path[i]);\n        if(i+1<len){\n            if(p->lchild&&p->lchild->data==path[i+1]) p=p->lchild;\n            else {p=p->rchild;assert(p&&p->data==path[i+1]);}\n        }\n    }\n    if(len) assert(!p->lchild&&!p->rchild);\n}\n\nstruct TGGraph {\n    ALGraph g{};\n    vector<vector<int>> a;\n    explicit TGGraph(int n):a(n,vector<int>(n,0)){g.vexnum=n;}\n    void add(int u,int v){\n        if(a[u][v]) return;\n        a[u][v]=1;\n        ArcNode *p=(ArcNode*)malloc(sizeof(ArcNode));\n        p->adjvex=v;p->nextarc=g.vertices[u].firstarc;\n        g.vertices[u].firstarc=p; ++g.arcnum;\n    }\n    ~TGGraph(){\n        for(int u=0;u<g.vexnum;++u){\n            ArcNode *p=g.vertices[u].firstarc;\n            while(p){ArcNode*q=p->nextarc;free(p);p=q;}\n        }\n    }\n};\nvector<vector<int>> TGReach(const TGGraph &g){\n    auto r=g.a;\n    int n=g.g.vexnum;\n    for(int k=0;k<n;++k)for(int i=0;i<n;++i)for(int j=0;j<n;++j)\n        r[i][j]=r[i][j]||(r[i][k]&&r[k][j]);\n    return r;\n}\nvoid TGTraversalCheck(const TGGraph &g){\n    int n=g.g.vexnum,out[MaxVertexNum];\n    auto reach=TGReach(g);\n    for(int mode=0;mode<2;++mode){\n        int count=mode?BFSForest(g.g,out):DFSForest(g.g,out);\n        assert(count==n);\n        vector<int> used(n,0);\n        int offset=0;\n        for(int root=0;root<n;++root){\n            if(used[root]) continue;\n            vector<int> group;\n            for(int v=0;v<n;++v)\n                if(!used[v]&&(v==root||reach[root][v])) group.push_back(v);\n            assert(out[offset]==root);\n            vector<int> got;\n            int previousDistance=-1;\n            vector<int> dist(n,n+1);dist[root]=0;\n            for(int step=0;step<n;++step)\n                for(int u=0;u<n;++u)for(int v=0;v<n;++v)\n                    if(!used[u]&&!used[v]&&g.a[u][v])\n                        dist[v]=std::min(dist[v],dist[u]+1);\n            for(size_t j=0;j<group.size();++j){\n                int v=out[offset++];\n                assert(v>=0&&v<n&&!used[v]);used[v]=1;got.push_back(v);\n                if(mode){assert(dist[v]>=previousDistance);previousDistance=dist[v];}\n            }\n            std::sort(got.begin(),got.end());assert(got==group);\n        }\n    }\n}\nbool TGTopoExpected(const TGGraph &g,const int seq[]){\n    int n=g.g.vexnum;vector<int> pos(n,-1);\n    for(int i=0;i<n;++i){\n        int v=seq[i]; if(v<0||v>=n||pos[v]!=-1)return false;pos[v]=i;\n    }\n    for(int u=0;u<n;++u)for(int v=0;v<n;++v)\n        if(g.a[u][v]&&pos[u]>=pos[v])return false;\n    return true;\n}\nbool TGPathExpected(const TGGraph &g,int s,int t,int k){\n    int n=g.g.vexnum;\n    vector<vector<bool>> dp(1<<n,vector<bool>(n,false));\n    dp[1<<s][s]=true;\n    for(int mask=0;mask<(1<<n);++mask){\n        int size=__builtin_popcount((unsigned)mask);\n        for(int u=0;u<n;++u)if(dp[mask][u]){\n            if(size==k+1&&u==t)return true;\n            if(size>k)continue;\n            for(int v=0;v<n;++v)\n                if(g.a[u][v]&&!(mask&(1<<v)))dp[mask|(1<<v)][v]=true;\n        }\n    }\n    return false;\n}\nint main(){\n    std::mt19937 rng(20261026);\n    int treeCases=0,pathCases=0,topoCases=0;\n    TGTreeCheck(NULL);++treeCases;\n    BiTree extrema=TGNew(INT_MIN);extrema->rchild=TGNew(INT_MAX);\n    TGTreeCheck(extrema);assert(JudgeBST(extrema));TGFree(extrema);++treeCases;\n    BiTree repeated=TGNew(2);repeated->lchild=TGNew(2);\n    assert(!JudgeBST(repeated));TGFree(repeated);\n    for(int c=0;c<250;++c){\n        int n=(int)(rng()%150)+1;\n        BiTree root=TGNew(-10000);vector<BiTree> open{root};\n        for(int i=1;i<n;++i){\n            int j=(int)(rng()%open.size());BiTree p=open[j],q=TGNew(i*7-10000);\n            if(!p->lchild&&!p->rchild){if(rng()%2)p->lchild=q;else p->rchild=q;}\n            else if(!p->lchild)p->lchild=q;else p->rchild=q;\n            if(p->lchild&&p->rchild){open[j]=open.back();open.pop_back();}\n            open.push_back(q);\n        }\n        TGTreeCheck(root);TGFree(root);++treeCases;\n    }\n    BiTree chain=NULL;\n    for(int i=MaxSize-1;i>=0;--i){BiTree p=TGNew(i);p->rchild=chain;chain=p;}\n    TGTreeCheck(chain);TGFree(chain);++treeCases;\n    {TGGraph g(6);g.add(0,2);g.add(0,1);g.add(1,3);g.add(2,4);\n     int a[6],b[6];DFSForest(g.g,a);BFSForest(g.g,b);\n     int x[]={0,1,3,2,4,5},y[]={0,1,2,3,4,5};\n     assert(std::equal(a,a+6,x)&&std::equal(b,b+6,y));}\n    for(int c=0;c<160;++c){\n        int n=(int)(rng()%8);TGGraph g(n);\n        for(int u=0;u<n;++u)for(int v=0;v<n;++v)\n            if(rng()%100<24)g.add(u,v);\n        TGTraversalCheck(g);\n        auto reach=TGReach(g);bool cycle=false;\n        for(int u=0;u<n;++u)cycle=cycle||reach[u][u];\n        int seq[MaxVertexNum];bool ok=TopologicalOrder(g.g,seq);\n        assert(ok==!cycle);if(ok)assert(TGTopoExpected(g,seq));++topoCases;\n        for(int p=0;p<24;++p){\n            std::iota(seq,seq+n,0);std::shuffle(seq,seq+n,rng);\n            assert(VerifyTopoOrder(g.g,seq)==TGTopoExpected(g,seq));++topoCases;\n        }\n        if(n){seq[0]=-1;assert(!VerifyTopoOrder(g.g,seq));\n            seq[0]=n;assert(!VerifyTopoOrder(g.g,seq));}\n        if(n>1){std::iota(seq,seq+n,0);seq[1]=seq[0];assert(!VerifyTopoOrder(g.g,seq));}\n        for(int test=0;test<32&&n;++test){\n            int s=(int)(rng()%n),t=(int)(rng()%n),k=(int)(rng()%n),path[MaxVertexNum];\n            bool found=FindExactPath(g.g,s,t,k,path);\n            assert(found==TGPathExpected(g,s,t,k));++pathCases;\n            if(found){\n                assert(path[0]==s&&path[k]==t);vector<int>used(n,0);\n                for(int i=0;i<=k;++i){assert(path[i]>=0&&path[i]<n&&!used[path[i]]++);\n                    if(i)assert(g.a[path[i-1]][path[i]]);}\n            }\n        }\n        int path[MaxVertexNum];assert(!FindExactPath(g.g,0,0,-1,path));\n        assert(!FindExactPath(g.g,0,0,n,path));\n    }\n    std::cout<<"PASS trees="<<treeCases<<" traversal_graphs=161 exact_paths="<<pathCases\n             <<" topo_checks="<<topoCases<<" plus_capacity_and_invalid_boundaries\\n";\n}\n'

TESTS['independent'] = '#include <cstdlib>\n#include <climits>\n#include <cassert>\n#include <algorithm>\n#include <vector>\n#include <set>\n#include <random>\n#include <iostream>\n\nvoid releaseTree(BiTree t){ if(!t)return; releaseTree(t->lchild); releaseTree(t->rchild); free(t); }\nint main(){\n std::mt19937 rng(20261026);\n for(int test=0;test<1200;++test){\n  int n=rng()%80; std::vector<int>a(n+1),expect;\n  for(int i=1;i<=n;++i)a[i]=int(rng()%31)-15;\n  expect=a;std::sort(expect.begin()+1,expect.end());\n  long long inversions=0;\n  for(int i=1;i<=n;++i)for(int j=i+1;j<=n;++j)inversions+=a[i]>a[j];\n  auto b=a;InsertSort(b.data(),n);assert(std::equal(b.begin()+1,b.end(),expect.begin()+1));\n  b=a;BubbleSort(b.data(),n);assert(std::equal(b.begin()+1,b.end(),expect.begin()+1));\n  b=a;QuickSort(b.data(),1,n);assert(std::equal(b.begin()+1,b.end(),expect.begin()+1));\n  b=a;HeapSort(b.data(),n);assert(std::equal(b.begin()+1,b.end(),expect.begin()+1));\n  b=a;assert(CountInversions(b.data(),n)==inversions);assert(std::equal(b.begin()+1,b.end(),expect.begin()+1));\n  b=a;MergeSort(b.data(),n);assert(std::equal(b.begin()+1,b.end(),expect.begin()+1));\n }\n for(int n=1;n<=35;++n)for(int s=1;s<=n;++s)for(int m=1;m<=15;++m){\n  std::vector<int> a;for(int i=1;i<=n;++i)a.push_back(i);\n  int pos=s-1;while(a.size()>1){pos=(pos+m-1)%a.size();a.erase(a.begin()+pos);}\n  assert(Josephus(n,s,m)==a[0]);\n }\n BiTree bst=NULL;std::set<int> keys;\n assert(BSTInsert(bst,INT_MIN));keys.insert(INT_MIN);\n assert(BSTInsert(bst,INT_MAX));keys.insert(INT_MAX);\n for(int i=0;i<5000;++i){\n  int key=int(rng()%301)-150;\n  if(rng()%2)assert(BSTInsert(bst,key)==keys.insert(key).second);\n  else assert(BSTDelete(bst,key)==bool(keys.erase(key)));\n  assert(JudgeBST(bst));\n  int a[MaxSize];int n=InOrderIter(bst,a);\n  assert(n==int(keys.size()));assert(std::equal(a,a+n,keys.begin()));\n  assert(bool(BSTSearch(bst,key))==bool(keys.count(key)));\n }\n releaseTree(bst);\n std::cout<<"PASS: 1200 sorting arrays; 9450 Josephus cases; 5000 BST updates\\n";\n}\n'

# Binary search is checked on 0-based views, independently of sorting internals.
TESTS['independent'] = TESTS['independent'].replace(
    'auto b=a;InsertSort',
    'for(int key=-20;key<=20;++key){int at=BinarySearch(expect.data()+1,n,key);'
    'bool present=std::find(expect.begin()+1,expect.end(),key)!=expect.end();'
    'assert((at!=-1)==present);if(at!=-1){assert(at>=0&&at<n);assert(expect[at+1]==key);}}\n'
    'auto b=a;InsertSort')


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--compiler', default=shutil.which('g++') or 'D:/Program Files/mingw64/bin/g++.exe')
    args=parser.parse_args()
    text=SOURCE.read_text(encoding='utf-8-sig')
    if re.findall(r'^### (\d{2}) ',text,re.M) != [f'{i:02d}' for i in range(1,24)]:
        raise ValueError('Expected exactly 23 ordered code entries')
    code='\n\n'.join(re.findall(r'```cpp\s*\n(.*?)\n```',text,re.S))
    destination=ROOT/'_tmp'
    destination.mkdir(exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='sprint_checks_',dir=destination) as directory:
        directory=Path(directory)
        for name,test in TESTS.items():
            cpp=directory/(name+'.cpp')
            exe=directory/(name+'.exe')
            cpp.write_text(code+'\n'+test,encoding='utf-8')
            subprocess.run([args.compiler,'-std=c++17','-O2','-Wall','-Wextra',
                            '-Werror','-pedantic',str(cpp),'-o',str(exe)],check=True)
            subprocess.run([str(exe)],check=True,timeout=90)
    print('PASS final source SHA256 '+hashlib.sha256(SOURCE.read_bytes()).hexdigest())

if __name__=='__main__':
    main()
